function mostNonOverlappingIntervals(intervals) {
  intervals.sort((a, b) => a[1] - b[1]);
  let count = 0;
  let prevEnd = -Infinity;
  for (const [l, r] of intervals) {
    if (l > prevEnd) {
      count++;
      prevEnd = r;
    }
  }
  return count;
}

