class MostNonOverlappingIntervals {
  public int solve(int[][] intervals) {
    Arrays.sort(intervals, Comparator.comparingInt(a -> a[1]));
    int count = 0;
    int prevEnd = Integer.MIN_VALUE;
    for (int[] interval : intervals) {
      if (interval[0] > prevEnd) {
        count++;
        prevEnd = interval[1];
      }
    }
    return count;
  }
}

